import { TreeDataNode } from '../types';
import { DataEntity, ShowCheckedStrategy, Value } from './interface';

function isCheckDisabled(node: TreeDataNode) {
  return !node || node.disabled;
}

export function formatStrategyValues(
  values: Value[],
  strategy: ShowCheckedStrategy,
  keyEntities: Record<Value, DataEntity>,
): Value[] {
  const valueSet = new Set(values);

  if (strategy === 'child') {
    return values.filter((key) => {
      const entity = keyEntities[key];
      return (
        !entity ||
        !entity.children ||
        !entity.children.some(({ node }) => valueSet.has(node.value)) ||
        !entity.children.every(({ node }) => isCheckDisabled(node) || valueSet.has(node.value))
      );
    });
  }
  if (strategy === 'parent') {
    return values.filter((key) => {
      const entity = keyEntities[key];
      const parent = entity ? entity.parent : null;
      return !parent || isCheckDisabled(parent.node) || !valueSet.has(parent.key as Value);
    });
  }
  return values;
}
