import { FunctionalComponent, h, VNode } from '@stencil/core';
import { JSXBase } from '@stencil/core/internal';

interface IndentProps {
  prefix: string;
  level: number;
  // We do not support isStart and isEnd for now, this is for indent line
  // isStart: boolean[];
  // isEnd: boolean[];
}

export const Indent: FunctionalComponent<IndentProps & JSXBase.IntrinsicElements['span']> = ({
  prefix,
  level,
  ...rest
}) => {
  const baseClassName = `${prefix}__indent`;
  const list: VNode[] = [];
  for (let i = 0; i < level; i++) {
    list.push(<span key={i} class={`${baseClassName}__unit`} data-testid={`ks-menu-item-indent-sq7fUZ-${i}`} />);
  }

  return (
    <span aria-hidden="true" class={baseClassName} {...rest}>
      {list}
    </span>
  );
};
