import { TreeDataNode } from '../types';
import { DataEntity, Value } from './interface';

export function processExpandParent(keyList: Value[], keyEntities: Record<Value, DataEntity<TreeDataNode>>) {
  const expandedKeys = new Set<Value>();

  function processUp(key: Value) {
    if (expandedKeys.has(key)) {
      return;
    }

    const entity = keyEntities[key];
    if (!entity) return;

    expandedKeys.add(key);

    const { parent, node } = entity;

    if (node.disabled) return;

    if (parent) {
      processUp(parent.key);
    }
  }

  (keyList || []).forEach((key) => {
    processUp(key);
  });

  return [...expandedKeys];
}
