/* eslint-disable max-lines */
import { Component, h, Element, Event, Host, State, Prop, Watch, EventEmitter, VNode } from '@stencil/core';
import { renderDynamicChildren, renderItemSlots, renderPassThroughSlots } from '@src/components/ks-menu-item/utils';
import { Value } from '@src/components/ks-menu-item/types';
import { TreeDataNode } from './types';
import {
  convertDataToEntities,
  DataEntity,
  FlattenNode,
  flattenTreeData,
  formatStrategyValues,
  processCheck,
  processExpandParent,
  ShowCheckedStrategy,
} from './utils';
import { KsVirtualList } from '@src/components/ks-virtual-list';
import { KsTreeItem } from '@src/components/ks-menu-item';
import { DetailArgs } from '@src/shared/dom';
import { TreeItemProps } from '@src/components/ks-menu-item/tree-item';
import { RenderConfig } from '@src/components/ks-virtual-list/types';
import { noop } from 'lodash-es';

const DEFAULT_HEIGHT = 36;
const DEFAULT_HEIGHT_WITH_DESC = 54;

@Component({
  tag: 'ks-tree-view',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTreeView extends KsVirtualList<FlattenNode<TreeDataNode>> {
  @Element() override el!: HTMLKsTreeViewElement;
  protected override prefixCls = 'tree-view';

  /** Whether to support multiple selection. */
  @Prop() multiple = false;

  /** Whether the tree view is disabled. */
  @Prop() disabled?: boolean;

  /** The tree view options. */
  @Prop() options: TreeDataNode[] = [];

  /** The keys of the expanded nodes. */
  @Prop() expandedKeys?: Value[];
  /** The default keys of the expanded nodes. */
  @Prop() defaultExpandedKeys?: Value[];
  @State() internalExpandedKeysState?: Value[];

  /** Whether to expand parent nodes when child nodes are expanded in the first render. */
  @Prop() defaultExpandParent = false;

  /** Whether to expand parent nodes when child nodes are expanded. */
  @Prop() autoExpandParent = false;

  /** Whether to expand all nodes by default. */
  @Prop() defaultExpandAll = false;

  /** Fired when the expanded nodes change. */
  @Event({ bubbles: false, composed: false }) ksExpand!: EventEmitter<
    DetailArgs<
      [
        Value[],
        {
          expanded: boolean;
          node: TreeDataNode;
        },
      ]
    >
  >;

  /** The keys of the checked nodes. */
  @Prop() checkedKeys?: Value[] | { checkedKeys: Value[]; halfCheckedKeys: Value[] };
  /** The default keys of the checked nodes. */
  @Prop() defaultCheckedKeys?: Value[] | { checkedKeys: Value[]; halfCheckedKeys: Value[] };
  /** Whether to check children nodes strictly. */
  @Prop() checkStrictly?: boolean;
  /** Fired when the checked nodes change. */
  @Event({ bubbles: false, composed: false }) ksCheck!: EventEmitter<
    DetailArgs<
      [
        Value[],
        {
          checked: boolean;
          checkedNodes: TreeDataNode[];
          halfCheckedKeys: Value[];
          node: TreeDataNode;
        },
      ]
    >
  >;

  /** Loads child nodes asynchronously when a tree node is expanded. */
  @Prop() loadData?: (treeNode: TreeDataNode) => Promise<void>;

  /** The keys of the loaded nodes. */
  @Prop() loadedKeys?: Value[];
  @Watch('loadedKeys')
  loadedKeysStateUpdate(newValue?: Value[]) {
    this.loadedKeysState = newValue || [];
  }
  private loadedKeysState: Value[] = [];
  @State() loadingKeys: Value[] = [];

  /** Whether the tree view is loading. */
  @Prop() loading = false;

  /** Custom filter function for tree nodes. */
  @Prop() filterTreeNode?: (node: TreeDataNode) => boolean;

  /** Specifies how to display checked nodes. */
  @Prop() showCheckedStrategy: ShowCheckedStrategy = 'all';

  /** The filtered tree view options. */
  @State() filteredTreeData: TreeDataNode[] = [];

  @Watch('options')
  @Watch('filterTreeNode')
  generateFilteredTreeData() {
    if (!this.filterTreeNode) {
      this.filteredTreeData = this.options;
      return;
    }
    const filterTreeNodes = (nodes: TreeDataNode[], keepAll = false): TreeDataNode[] =>
      nodes.reduce<TreeDataNode[]>((filtered, node) => {
        const { children } = node;
        const isMatch = keepAll || this.filterTreeNode?.(node);
        const filteredChildren = filterTreeNodes(children || [], isMatch);

        if (isMatch || filteredChildren.length) {
          filtered.push({
            ...node,
            isLeaf: undefined,
            ['children']: filteredChildren,
          });
        }
        return filtered;
      }, []);

    this.filteredTreeData = filterTreeNodes(this.options);
  }

  /** Fired when a node is loaded. */
  @Event({ bubbles: false, composed: false }) ksLoad!: EventEmitter<DetailArgs<[Value[], TreeDataNode]>>;

  /** Specifies if the list should enable virtualized scrolling. */
  @Prop() virtual?: boolean | { estimatedItemHeight: number | ((item: FlattenNode<TreeDataNode>) => number) } = true;

  // override ks virtual list
  @State() override items: FlattenNode<TreeDataNode>[] = [];
  protected override DEFAULT_HEIGHT = (item: FlattenNode<TreeDataNode>) => {
    const { data } = item;
    return data.description ? DEFAULT_HEIGHT_WITH_DESC : DEFAULT_HEIGHT;
  };
  protected override renderItem(item: FlattenNode<TreeDataNode>, index: number) {
    const { data } = item;
    const { value: key } = data;

    // merge states for render
    const mergedChecked = this.checkedState.checkedKeys.includes(key);
    const mergedHalfChecked = this.checkedState.halfCheckedKeys.includes(key);
    const mergedDisabled = data.disabled || this.disabled;

    let expanded = undefined;
    if (data.children?.length || data.isLeaf === false) {
      expanded = this.internalExpandedKeysState?.includes(key) || false;
    }

    const { level } = this.keyEntities[key]!;
    return (
      <KsTreeItem
        {...data}
        multiple={this.multiple}
        value={key}
        checked={mergedChecked}
        disabled={mergedDisabled}
        label={typeof data.label === 'string' ? data.label : undefined}
        description={typeof data.description === 'string' ? data.description : undefined}
        helpContent={typeof data.helpContent === 'string' ? data.helpContent : undefined}
        popover={data.popover}
        indeterminate={mergedHalfChecked}
        expanded={expanded}
        indent={level}
        onClick={(value, event) => {
          data.onClick?.(value, event);
          if (expanded === undefined || this.multiple) {
            this.onNodeCheck(data, !mergedChecked);
          } else {
            this.onNodeExpand(data);
          }
        }}
        onExpand={(e: PointerEvent) => {
          e.stopPropagation();
          this.onNodeExpand(data);
        }}
        loading={this.loadingKeys.includes(key)}
        highlight={(data as TreeDataNode & { highlight?: TreeItemProps['highlight'] }).highlight || null}
      >
        {renderItemSlots(data, index)}
      </KsTreeItem>
    );
  }
  protected override getPassThroughSlots = (item: FlattenNode<TreeDataNode>, index: number) =>
    renderPassThroughSlots(item.data, index);
  protected renderDynamicChildrenForItem(
    item: FlattenNode<TreeDataNode>,
    index: number,
    wrapWithSlot: (slotName: string, children: unknown) => unknown,
    renderConfig?: RenderConfig,
  ): unknown[] {
    return renderDynamicChildren(item.data, index, wrapWithSlot, renderConfig);
  }

  render() {
    return (
      <Host class="KsTreeView">
        <ks-spinner loading={!!this.loading}>{this.renderList()}</ks-spinner>
      </Host>
    );
  }

  // eslint-disable-next-line @typescript-eslint/no-useless-constructor
  constructor() {
    super();
  }

  override connectedCallback() {
    super.connectedCallback?.();
  }

  override disconnectedCallback() {
    super.disconnectedCallback?.();
  }

  override componentDidRender(): void {
    super.componentDidRender();
  }

  override componentWillLoad(): Promise<void> | void {
    this.handleOptionsChange();
    this.generateFilteredTreeData();
    this.prepareItemsForRender();
    this.handleCheckedKeysChange();
    this.handleExpandedKeysChange(this.expandedKeys);
    super.componentWillLoad();
  }

  private keyEntities: Record<Value, DataEntity<TreeDataNode>> = {};

  @Watch('options')
  handleOptionsChange() {
    const entitiesMap = convertDataToEntities(this.options);
    this.keyEntities = entitiesMap.keyEntities;
  }

  @Watch('filteredTreeData')
  @Watch('internalExpandedKeysState')
  prepareItemsForRender() {
    this.items = flattenTreeData<TreeDataNode>(this.filteredTreeData, this.internalExpandedKeysState || []);
  }

  @State() checkedState: { checkedKeys: Value[]; halfCheckedKeys: Value[] } = {
    checkedKeys: [],
    halfCheckedKeys: [],
  };
  @Watch('checkedKeys')
  handleCheckedKeysChange() {
    const mergedCheckedKeys = this.checkedKeys || this.defaultCheckedKeys;
    let checkedKeys: Value[] = [];
    let halfCheckedKeys: Value[] = [];
    if (Array.isArray(mergedCheckedKeys)) {
      checkedKeys = mergedCheckedKeys;
    } else if (typeof mergedCheckedKeys === 'object') {
      ({ checkedKeys, halfCheckedKeys } = mergedCheckedKeys);
    }
    if (!this.checkStrictly) {
      ({ checkedKeys, halfCheckedKeys } = processCheck(checkedKeys, true, this.keyEntities));
    }
    this.checkedState = { checkedKeys, halfCheckedKeys };
  }

  private onNodeCheck = (treeNode: TreeDataNode, checked: boolean) => {
    const { value: key } = treeNode;
    if (!this.multiple) {
      // ====== single mode ======
      if (this.checkedKeys === undefined) {
        this.checkedState = {
          checkedKeys: [key],
          halfCheckedKeys: [],
        };
      }
      this.ksCheck.emit(
        DetailArgs([key], {
          checked,
          checkedNodes: [treeNode],
          halfCheckedKeys: [],
          node: treeNode,
        }),
      );
      return;
    } else {
      // ====== multiple mode ======
      let checkedObj: Value[];
      const eventObj: {
        checked: boolean;
        checkedNodes: TreeDataNode[];
        halfCheckedKeys: Value[];
        node: TreeDataNode;
      } = {
        checked,
        checkedNodes: [],
        halfCheckedKeys: [],
        node: treeNode,
      };

      const { checkedKeys: oriCheckedKeys, halfCheckedKeys: oriHalfCheckedKeys } = this.checkedState;

      if (this.checkStrictly) {
        // ====== check strictly in multiple mode ======
        const checkedKeys = checked ? [...oriCheckedKeys, key] : oriCheckedKeys.filter((item) => item !== key);
        const halfCheckedKeys = oriHalfCheckedKeys.filter((item) => item !== key);

        checkedObj = checkedKeys;
        if (this.checkedKeys === undefined) {
          // uncontrolled
          this.checkedState = { ...this.checkedState, checkedKeys };
        }

        eventObj.halfCheckedKeys = halfCheckedKeys;
        checkedKeys.forEach((checkedKey) => {
          const entity = this.keyEntities[checkedKey];
          if (!entity) return;

          const { node } = entity;
          eventObj.checkedNodes.push(node);
        });
      } else {
        // ====== normal multiple mode ======

        // fill first
        let { checkedKeys, halfCheckedKeys } = processCheck([...oriCheckedKeys, key], true, this.keyEntities);

        // if check is remove, we do it again to correct
        if (!checked) {
          const keySet = new Set(checkedKeys);
          keySet.delete(key);
          ({ checkedKeys, halfCheckedKeys } = processCheck(
            Array.from(keySet),
            { checked: false, halfCheckedKeys },
            this.keyEntities,
          ));
        }

        checkedObj = checkedKeys;

        // format based on showCheckedStrategy
        checkedObj = formatStrategyValues(checkedObj, this.showCheckedStrategy, this.keyEntities);

        eventObj.halfCheckedKeys = halfCheckedKeys;
        checkedKeys.forEach((checkedKey) => {
          const entity = this.keyEntities[checkedKey];
          if (!entity) return;

          const { node } = entity;
          eventObj.checkedNodes.push(node);
        });

        if (this.checkedKeys === undefined) {
          // uncontrolled
          this.checkedState = { checkedKeys, halfCheckedKeys };
        }
      }

      this.ksCheck.emit(DetailArgs(checkedObj, eventObj));
    }
  };

  private onNodeLoad = async (treeNode: TreeDataNode) => {
    const { value: key } = treeNode;

    // Skip if already have children
    const entity = this.keyEntities[key];
    if (entity?.children?.length) {
      return;
    }

    if (!this.loadData || this.loadedKeysState.includes(key) || this.loadingKeys.includes(key)) {
      return;
    }

    this.loadingKeys = [...this.loadingKeys, key];

    try {
      await this.loadData(treeNode);
      const newLoadedKeys = [...this.loadedKeysState, key];

      if (this.loadedKeys === undefined) {
        // uncontrolled
        this.loadedKeysState = newLoadedKeys;
      }
      this.ksLoad.emit(DetailArgs(newLoadedKeys, treeNode));
    } catch (error) {
      // TODO: Process error
      console.error('KsTreeView onNodeLoad error:', error);
      throw error;
    } finally {
      this.loadingKeys = this.loadingKeys.filter((item) => item !== key);
    }
  };

  @Watch('expandedKeys')
  handleExpandedKeysChange(_?: Value[], oldExpandedKeys?: Value[]) {
    const mergedExpandedKeys = this.expandedKeys || this.defaultExpandedKeys || [];

    let newExpandedKeysState: Value[] = [];

    if (!oldExpandedKeys) {
      // is init, no previous keys
      if (this.defaultExpandAll) {
        newExpandedKeysState = Object.keys(this.keyEntities).filter((key) => {
          const entity = this.keyEntities[key];
          return entity?.children?.length;
        });
      } else if (this.defaultExpandParent || this.autoExpandParent) {
        newExpandedKeysState = processExpandParent(mergedExpandedKeys, this.keyEntities);
      } else {
        // expand normally
        newExpandedKeysState = mergedExpandedKeys;
      }
    } else {
      // when auto expand is true, we need to expand all parent nodes
      newExpandedKeysState = this.autoExpandParent
        ? processExpandParent(mergedExpandedKeys, this.keyEntities)
        : mergedExpandedKeys;
    }
    this.internalExpandedKeysState = newExpandedKeysState;
  }

  private onNodeExpand = (treeNode: TreeDataNode) => {
    const { value: key } = treeNode;
    const expanded = this.internalExpandedKeysState?.includes(key);
    const targetExpanded = !expanded;

    // Prepare config obj for ksExpand event
    const expandEventConfig = {
      expanded: targetExpanded,
      node: treeNode,
    };
    const nextExpandedKeys = targetExpanded
      ? [...(this.internalExpandedKeysState || []), key]
      : (this.internalExpandedKeysState || []).filter((item) => item !== key);

    if (this.expandedKeys === undefined) {
      // uncontrolled mode
      this.internalExpandedKeysState = nextExpandedKeys;
    }
    // trigger event
    this.ksExpand.emit(DetailArgs(nextExpandedKeys, expandEventConfig));

    if (targetExpanded && this.loadData) {
      this.onNodeLoad(treeNode);
    }
  };

  /**
   * @private */
  @Prop() override wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /**
   * @private */
  @Prop() override setDynamicRenderDeps: (children: unknown[], getPassThroughSlots?: () => VNode[]) => void = noop;

  ////// DEPS //////
  protected __DEPS__() {
    // istanbul ignore next
    return [<ks-checkbox />, <ks-tooltip />, <ks-text />];
  }
}
