import { Fragment, h, VNode } from '@stencil/core';
import { KsMenuItemBase, MenuItemBaseProps } from './item';
import { Indent } from './indent';
import { TreeDataNode } from '@src/components';
import { KsIconFilledChevronDown } from '@fe-infra/keystone-icons-stencil';

const prefix = 'tree-item';

export interface TreeItemProps extends MenuItemBaseProps<TreeDataNode> {
  classes?: {
    [className: string]: boolean;
  };
  loading?: boolean;
  indent?: number;
  expanded?: boolean;
  onExpand?: (e: PointerEvent) => void;
}

export const KsTreeItem = (
  { classes = {}, indent = 0, expanded, onExpand, loading, ...rest }: TreeItemProps,
  children: VNode[],
) => {
  const { multiple, disabled, checked } = rest;
  const expandable = expanded !== undefined;
  const mergedActive = !multiple && checked;
  return (
    <Fragment>
      <KsMenuItemBase<TreeDataNode>
        classes={{
          [prefix]: true,
          [`${prefix}--active`]: checked,
          [`${prefix}--disabled`]: disabled || false,
          ...classes,
        }}
        active={mergedActive}
        {...rest}
      >
        <Indent slot="before" prefix={prefix} level={indent} />
        <div
          slot="before"
          class={{
            [`${prefix}__chevron`]: true,
            [`${prefix}__chevron--hidden`]: !expandable,
          }}
          onClick={(e: PointerEvent) => {
            if (expandable) {
              onExpand?.(e);
            }
          }}
          data-testid="ks-menu-item-tree-item-7FunpW"
        >
          <KsIconFilledChevronDown
            size={12}
            class={{
              [`${prefix}__chevron--icon`]: true,
              [`${prefix}__chevron--icon--expanded`]: expanded || false,
            }}
            data-testid="ks-menu-item-tree-item-r2rxix"
          />
        </div>
        {children}
      </KsMenuItemBase>
      {loading && (
        <ks-spinner>
          <div style={{ width: '100%', height: 'var(--ks-spacing-9)' }} />
        </ks-spinner>
      )}
    </Fragment>
  );
};
